package com.asmj.marketplace.printout.service;
import com.asmj.marketplace.printout.dto.PrintoutDtos.*; import com.asmj.marketplace.printout.model.PrintoutRequest; import com.asmj.marketplace.printout.model.PrintoutRequest.DocumentFile; import com.asmj.marketplace.printout.model.PrintoutService; import com.asmj.marketplace.printout.repository.*; import com.asmj.marketplace.user.repository.UserRepository; import com.asmj.marketplace.vendor.repository.VendorRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.math.*; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class PrintoutRequestManager { private final PrintoutRequestRepository requests; private final PrintoutServiceRepository services; private final UserRepository users; private final VendorRepository vendors;
 private String uid(String e){return users.findByEmailIgnoreCase(e).orElseThrow().getId();} private String num(){return "PR-"+System.currentTimeMillis();}
 public List<PrintoutRequest> mine(String e){return requests.findByCustomerIdOrderByCreatedAtDesc(uid(e));} public List<PrintoutRequest> vendor(String e){return requests.findByVendorIdOrderByCreatedAtDesc(vendors.findByUserId(uid(e)).orElseThrow().getId());}
 public PrintoutRequest create(String e,RequestCreate r){var c=users.findByEmailIgnoreCase(e).orElseThrow();var s=services.findById(r.printoutServiceId()).orElseThrow();if(!s.isActive())throw new IllegalArgumentException("Service is not active");if("HOME_DELIVERY".equals(r.fulfilmentType())&&!s.isHomeDeliveryAvailable())throw new IllegalArgumentException("Home delivery is not available");if("PICKUP".equals(r.fulfilmentType())&&!s.isPickupAvailable())throw new IllegalArgumentException("Pickup is not available");int pages=r.pageCount()==null?1:r.pageCount(), copies=r.copies()==null?1:r.copies();BigDecimal rate=("COLOR".equalsIgnoreCase(r.printMode())?("DOUBLE".equalsIgnoreCase(r.printSide())?s.getColorDoubleRate():s.getColorSingleRate()):("DOUBLE".equalsIgnoreCase(r.printSide())?s.getBwDoubleRate():s.getBwSingleRate()));BigDecimal printing=rate.multiply(BigDecimal.valueOf(pages)).multiply(BigDecimal.valueOf(copies));if("A3".equalsIgnoreCase(r.paperSize()))printing=printing.add(s.getA3AdditionalCharge().multiply(BigDecimal.valueOf(pages)).multiply(BigDecimal.valueOf(copies)));BigDecimal binding="NONE".equalsIgnoreCase(r.bindingType())?BigDecimal.ZERO:s.getBindingCharge();BigDecimal lam=Boolean.TRUE.equals(r.laminationRequired())?s.getLaminationCharge():BigDecimal.ZERO;BigDecimal delivery=BigDecimal.ZERO;if("HOME_DELIVERY".equals(r.fulfilmentType())){if(printing.compareTo(s.getMinimumHomeDeliveryAmount())<0)throw new IllegalArgumentException("Minimum home-delivery order is ₹"+s.getMinimumHomeDeliveryAmount());delivery=printing.multiply(s.getHomeDeliveryChargePercent()).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);}var x=PrintoutRequest.builder().requestNumber(num()).customerId(c.getId()).vendorId(s.getVendorId()).printoutServiceId(s.getId()).documentName(r.documentName()).files(r.files()==null?List.of():r.files().stream().map(f->DocumentFile.builder().fileName(f.fileName()).url(f.url()).publicId(f.publicId()).build()).toList()).copies(copies).pageCount(pages).printMode(r.printMode()).paperSize(r.paperSize()).printSide(r.printSide()).bindingType(r.bindingType()).laminationRequired(Boolean.TRUE.equals(r.laminationRequired())).fulfilmentType(r.fulfilmentType()).deliveryAddress(r.deliveryAddress()).deliveryLandmark(r.deliveryLandmark()).deliveryCity(r.deliveryCity()).deliveryState(r.deliveryState()).deliveryPincode(r.deliveryPincode()).contactNumber(r.contactNumber()).specialInstructions(r.specialInstructions()).printingAmount(printing).bindingAmount(binding).laminationAmount(lam).deliveryCharge(delivery).totalAmount(printing.add(binding).add(lam).add(delivery)).status(PrintoutRequest.Status.SUBMITTED).createdAt(Instant.now()).updatedAt(Instant.now()).build();return requests.save(x);}
 public PrintoutRequest status(String email,String id,StatusRequest r){var x=requests.findById(id).orElseThrow();String u=uid(email);boolean owner=x.getCustomerId().equals(u)||vendors.findByUserId(u).map(v->v.getId().equals(x.getVendorId())).orElse(false);if(!owner)throw new IllegalArgumentException("Not authorized");x.setStatus(PrintoutRequest.Status.valueOf(r.status()));x.setVendorRemarks(r.vendorRemarks());if(r.quotedAmount()!=null){x.setQuotedAmount(r.quotedAmount());x.setPaymentStatus("PAYMENT_PENDING");}x.setUpdatedAt(Instant.now());return requests.save(x);}
 public List<PrintoutRequest> pendingPaymentProofs(){return requests.findAll().stream().filter(x->x.getPaymentProofUrl()!=null&&!x.getPaymentProofUrl().isBlank()&&"PENDING_REVIEW".equalsIgnoreCase(x.getPaymentStatus())).sorted(Comparator.comparing(PrintoutRequest::getUpdatedAt,Comparator.nullsLast(Comparator.reverseOrder()))).toList();}
 public PrintoutRequest reviewPaymentProof(String id,String status,String reason){if(status==null||!Set.of("VERIFIED","REJECTED").contains(status))throw new IllegalArgumentException("Status must be VERIFIED or REJECTED");var x=requests.findById(id).orElseThrow(()->new IllegalArgumentException("Printout request not found"));if(x.getPaymentProofUrl()==null||x.getPaymentProofUrl().isBlank())throw new IllegalArgumentException("No payment proof has been submitted for this printout request");x.setPaymentStatus("VERIFIED".equals(status)?"PAID":"REJECTED");if("REJECTED".equals(status))x.setVendorRemarks((x.getVendorRemarks()==null?"":x.getVendorRemarks()+" | ")+"Payment proof rejected: "+(reason==null||reason.isBlank()?"Proof could not be verified":reason));x.setUpdatedAt(Instant.now());return requests.save(x);}

 public PrintoutRequest paymentProof(String email,String id,PaymentProofRequest r){if(r==null||r.paymentProofUrl()==null||r.paymentProofUrl().isBlank())throw new IllegalArgumentException("Payment proof file is required");if(r.paymentReference()==null||r.paymentReference().isBlank())throw new IllegalArgumentException("Payment reference is required");var x=requests.findById(id).orElseThrow();String u=uid(email);if(!x.getCustomerId().equals(u))throw new IllegalArgumentException("Only the customer can upload payment proof");x.setPaymentProofUrl(r.paymentProofUrl());x.setPaymentProofPublicId(r.paymentProofPublicId());x.setPaymentReference(r.paymentReference());x.setPaymentStatus("PENDING_REVIEW");if(r.amount()!=null)x.setQuotedAmount(r.amount());x.setUpdatedAt(Instant.now());return requests.save(x);}
}
